BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: medium / L3 — Pattern of misstatements indicating systematic bias
(1, 'Misstatements and Control Deficiencies', 'During the audit of Greenfield Enterprises, the engagement team discovers three individually immaterial misstatements totaling $38,000 in the revenue cycle. Performance materiality is $45,000 and overall materiality is $60,000. The auditor should analyze the pattern of these misstatements because it most likely indicates:', '["The financial statements contain a material misstatement requiring opinion modification", "A possible systematic bias in the revenue recognition process that may signal additional undetected errors", "Performance materiality was set too high and must be revised downward immediately", "The three misstatements should be treated as a single material misstatement for reporting purposes"]'::jsonb, 1, 'Under AU-C 450.A16, when the auditor identifies a pattern of misstatements in the same account or class of transactions, this may indicate a systematic cause that could result in additional undetected misstatements. The auditor should investigate whether the revenue cycle contains further errors because the pattern suggests a process failure. While choice A is premature—the misstatements are below materiality—the pattern warrants expanded procedures rather than immediate opinion modification.', 'medium', 3),

-- Q2: easy / L1 — Clearly trivial threshold definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what is the threshold below which misstatements need not be accumulated during an audit?', '["Clearly trivial", "Quantitatively immaterial", "Below performance materiality", "Less than tolerable misstatement"]'::jsonb, 0, 'Under AU-C 450.05, the auditor is required to accumulate all misstatements identified during the audit except those that are clearly trivial. Clearly trivial means amounts that are inconsequential whether taken individually or in the aggregate, typically well below materiality. Choice B is incorrect because immaterial misstatements that are not clearly trivial must still be accumulated and evaluated in aggregate.', 'easy', 1),

-- Q3: medium / L3 — Management bias in estimates
(1, 'Misstatements and Control Deficiencies', 'Birchwood Financial Group estimates its loan loss reserve at $1.2 million, but the auditor''s independent estimate using the same data and assumptions yields $1.8 million. Management insists their estimate is within a reasonable range. The auditor should analyze this $600,000 difference primarily to determine whether:', '["The difference exceeds the tolerable misstatement established for the audit", "Management should be required to adjust the financial statements before the audit report is issued", "The estimate reflects a possible management bias that could indicate additional judgmental misstatements", "The loan loss reserve should be reclassified from an estimate to a contingent liability"]'::jsonb, 2, 'Under AU-C 540.21, the auditor must evaluate whether differences between management''s estimates and the auditor''s estimates indicate possible management bias. A consistent pattern of favorable estimates may signal intentional understatement of reserves. Choice A focuses only on quantitative assessment, while the primary concern here is evaluating whether management bias exists, which could affect estimates across the financial statements.', 'medium', 3),

-- Q4: medium / L2 — Written representation for uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'After completing the audit of Summit Ridge Holdings for the year ended December 31, 2025, the auditor presents management with a summary of $28,000 in uncorrected misstatements, all below the $75,000 materiality threshold. Under AU-C 450, management must provide:', '["A signed statement that no additional misstatements exist beyond those identified", "Written assurance that all significant deficiencies related to the misstatements have been remediated", "A formal action plan documenting how each misstatement will be corrected in the subsequent period", "A written representation that the effects of uncorrected misstatements are immaterial to the financial statements"]'::jsonb, 3, 'Under AU-C 450.14, the auditor must obtain a written representation from management that the effects of uncorrected misstatements are immaterial, individually and in the aggregate, to the financial statements as a whole. This representation must be included in the management representation letter. Choice C is incorrect because AU-C 450 does not require management to commit to correcting immaterial misstatements in future periods.', 'medium', 2),

-- Q5: medium / L3 — Prior-period misstatement reversal effect
(1, 'Misstatements and Control Deficiencies', 'During the prior-year audit of Redstone Manufacturing, a $35,000 inventory overstatement was identified but left uncorrected. In the current year, the auditor determines the misstatement has reversed through cost of goods sold. The auditor should analyze the effect of this reversal because:', '["The prior-period misstatement must be corrected through a restatement before the current-year audit can proceed", "The reversal creates a current-year understatement of income that must be included in the aggregate of current-year misstatements", "Prior-period misstatements that reverse automatically are removed from the summary of uncorrected misstatements", "The reversal eliminates the need to evaluate the prior-period misstatement in the current-year audit"]'::jsonb, 1, 'Under AU-C 450.A7, prior-period uncorrected misstatements that reverse in the current period affect the current-year financial statements. The auditor must consider the effect of such reversals when evaluating the aggregate of current-year misstatements because the reversal creates a misstatement in the opposite direction. Choice D is incorrect because the reversing effect requires evaluation—it does not eliminate the auditor''s responsibility to assess its impact.', 'medium', 3),

-- Q6: easy / L1 — Three categories of misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what are the three categories of misstatements the auditor must consider?', '["Factual misstatements, judgmental misstatements, and projected misstatements", "Material misstatements, immaterial misstatements, and trivial misstatements", "Quantitative misstatements, qualitative misstatements, and pervasive misstatements", "Known misstatements, likely misstatements, and possible misstatements"]'::jsonb, 0, 'Under AU-C 450.A1–A3, misstatements are classified as factual (no doubt about existence), judgmental (arising from differences in management''s judgments about estimates), and projected (extrapolated from audit sample results to the population). Choice D is incorrect because it uses older terminology from superseded standards and does not reflect current AU-C 450 classifications.', 'easy', 1),

-- Q7: hard / L3 — Intentional misclassification as fraud
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cascade Properties Inc., the auditor discovers that management intentionally reclassified $450,000 of operating expenses as capital improvements to meet debt covenant ratios for the quarter ended September 30, 2025. The financial statements are materially misstated. This intentional misclassification most likely indicates:', '["A judgmental misstatement arising from a reasonable difference of opinion about capitalization criteria", "A control deficiency in the accounts payable department''s review process", "A fraudulent misstatement requiring evaluation under AU-C 240 and communication to those charged with governance", "A significant deficiency that should be communicated in writing within 60 days of the report release date"]'::jsonb, 2, 'Under AU-C 240.06, fraud involves intentional acts that result in material misstatements of financial statements. Because management deliberately reclassified expenses to meet covenant requirements, this constitutes fraudulent financial reporting, not merely an error or control deficiency. The auditor must evaluate implications under AU-C 240 and communicate the finding to governance. Choice A is incorrect because intentional misclassification to meet covenants is not a good-faith judgment difference.', 'hard', 3),

-- Q8: medium / L3 — IT general control deficiency with pervasive impact
(1, 'Misstatements and Control Deficiencies', 'During the audit of Northstar Data Services, the auditor discovers that the IT administrator account has unrestricted access to modify transaction records in the general ledger without logging or approval. This finding most likely represents:', '["An isolated control deficiency limited to logical access management", "A reportable condition that the auditor may communicate orally to management", "A deficiency in application controls that affects only the general ledger module", "A pervasive IT general control deficiency that could undermine the reliability of multiple automated controls"]'::jsonb, 3, 'Under AU-C 265.A8, IT general controls such as access management are foundational to the control environment. When an IT administrator can modify records without logging, the deficiency is pervasive because it undermines the integrity of all application controls that depend on the IT environment. This likely constitutes a material weakness. Choice A is incorrect because it treats the finding as isolated, whereas unrestricted administrative access has enterprise-wide implications.', 'medium', 3),

-- Q9: medium / L2 — Summary of uncorrected misstatements content
(1, 'Misstatements and Control Deficiencies', 'Meridian Consulting LLC''s audit for the year ended December 31, 2025 identifies six misstatements. Management corrects four but declines to adjust a $12,000 accounts receivable error and a $9,500 prepaid expense error. The auditor''s summary of uncorrected misstatements should include:', '["All six identified misstatements regardless of whether management corrected them", "Only the $12,000 accounts receivable error and the $9,500 prepaid expense error that management declined to correct", "Only misstatements that individually exceed performance materiality", "The four corrected misstatements plus a notation that management refused to adjust the remaining two"]'::jsonb, 1, 'Under AU-C 450.12, the auditor must communicate all uncorrected misstatements to those charged with governance and request correction. The summary of uncorrected misstatements includes only those misstatements that management has not corrected. Choice A is incorrect because corrected misstatements are removed from the summary, though the auditor may still consider them when assessing control effectiveness.', 'medium', 2),

-- Q10: hard / L4 — Qualitatively material misstatement involving management integrity
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ironclad Security Corp., the auditor identifies a $22,000 misstatement where the CEO''s personal travel expenses were charged to the company and disclosed as business expenses. Overall materiality is $200,000. Management refuses to correct the misstatement or revise disclosures, arguing it is clearly immaterial. The auditor should evaluate whether:', '["The misstatement is qualitatively material due to its nature involving related-party transactions and potential management integrity concerns", "The opinion should remain unmodified because the misstatement is quantitatively well below the materiality threshold", "The misstatement should be removed from the summary of uncorrected misstatements since it involves a governance matter", "Communication to the audit committee satisfies the auditor''s obligation and no further action is required"]'::jsonb, 0, 'Under AU-C 450.11, the auditor must consider both quantitative and qualitative factors when evaluating whether uncorrected misstatements are material. A misstatement involving personal expenses of a senior executive disguised as business expenses raises management integrity concerns and related-party disclosure issues under AU-C 550. Choice B is incorrect because it focuses solely on quantitative materiality, whereas the qualitative significance of management integrity concerns must also be evaluated.', 'hard', 4),

-- Q11: medium / L3 — Prior-year unremediated material weakness recommunication
(1, 'Misstatements and Control Deficiencies', 'During the current-year audit of Clearwater Distributing, the auditor notes that a material weakness in inventory controls communicated in the prior-year audit has not been remediated. Management acknowledges the deficiency but states remediation is planned for next quarter. The auditor''s most appropriate response is to:', '["Reference the prior-year communication and note that no new communication is required since the deficiency was previously reported", "Orally communicate the unremediated deficiency to the audit committee and document the discussion in the working papers", "Withhold the audit opinion until management provides a written remediation timeline", "Issue a new written communication to those charged with governance describing the unremediated material weakness"]'::jsonb, 3, 'Under AU-C 265.13, if a previously communicated significant deficiency or material weakness has not been remediated, the auditor must communicate it again in writing during the current period. Repeating the communication ensures those charged with governance remain aware of unresolved risks. Choice A is incorrect because AU-C 265 requires fresh communication each period regardless of whether the deficiency was previously reported.', 'medium', 3),

-- Q12: hard / L4 — Combined deficiencies constituting material weakness
(1, 'Misstatements and Control Deficiencies', 'While auditing Pinnacle Health Systems, the engagement team identifies three control deficiencies: (1) the revenue cycle lacks segregation of duties between billing and collections, (2) journal entry approvals are not enforced for entries under $50,000, and (3) the month-end close checklist is not consistently followed. Individually, each deficiency appears to be a significant deficiency. The auditor should evaluate whether:', '["Each deficiency should be communicated separately with individual remediation recommendations", "The deficiencies should be ranked by severity and only the most serious one classified as a material weakness", "The three deficiencies offset each other because they relate to different financial statement areas", "The combination of deficiencies constitutes a material weakness because together they create a reasonable possibility of material misstatement"]'::jsonb, 3, 'Under AU-C 265.A13, the auditor must consider whether individually less severe deficiencies, when combined, represent a material weakness. Three deficiencies affecting revenue, journal entries, and financial close processes collectively undermine the control environment''s ability to prevent or detect material misstatements. Choice C is incorrect because deficiencies in different areas do not offset each other—they compound the overall control risk.', 'hard', 4),

-- Q13: easy / L2 — Accumulating identified misstatements
(1, 'Misstatements and Control Deficiencies', 'During testing at Lakeview Electronics, the audit team identifies a $3,200 depreciation error and a $1,800 inventory pricing error. Performance materiality is $40,000. Under AU-C 450, the auditor should:', '["Accumulate both misstatements on the summary of identified misstatements for aggregate evaluation", "Disregard both misstatements because they are individually below performance materiality", "Communicate both misstatements to management only if their combined total exceeds performance materiality", "Record the misstatements in the working papers but exclude them from the aggregate evaluation"]'::jsonb, 0, 'Under AU-C 450.05, the auditor must accumulate all identified misstatements during the audit except those that are clearly trivial. Even though each misstatement is small relative to performance materiality, both must be accumulated for aggregate evaluation. Choice B is incorrect because the threshold for accumulation is clearly trivial, not performance materiality, and $3,200 and $1,800 are unlikely to be clearly trivial amounts.', 'easy', 2),

-- Q14: medium / L2 — Duplicate payment indicating control deficiency
(1, 'Misstatements and Control Deficiencies', 'During the audit of Harborview Marine Supply for the year ended June 30, 2025, the auditor discovers that a $67,000 purchase was recorded twice due to the accounts payable clerk entering the same invoice number on two different dates. Under AU-C 265, this duplicate payment most likely indicates:', '["A projected misstatement that must be extrapolated to the entire accounts payable population", "A factual misstatement that requires opinion modification if management refuses to correct it", "An anomalous error that does not suggest a control deficiency unless additional duplicates are found", "A control deficiency in the duplicate invoice detection process within the accounts payable system"]'::jsonb, 3, 'Under AU-C 265.A5, a control deficiency exists when a control is designed, implemented, or operated in a way that does not allow management or employees to prevent or detect misstatements on a timely basis. A duplicate payment indicates the system lacks effective duplicate invoice checking controls. Choice C is incorrect because even a single instance of a failed preventive control indicates a deficiency in control design or operation.', 'medium', 2),

-- Q15: easy / L1 — Purpose of performance materiality
(1, 'Misstatements and Control Deficiencies', 'What is the purpose of setting performance materiality below overall materiality in an audit?', '["To reduce the probability that the aggregate of uncorrected and undetected misstatements exceeds overall materiality", "To establish the threshold for communicating control deficiencies to those charged with governance", "To determine the minimum dollar amount of misstatements that must be reported to management", "To set the clearly trivial threshold below which misstatements need not be accumulated"]'::jsonb, 0, 'Under AU-C 320.09, performance materiality is set below overall materiality to reduce to an appropriately low level the probability that the aggregate of uncorrected and undetected misstatements exceeds materiality for the financial statements as a whole. Choice D is incorrect because the clearly trivial threshold is a separate, lower amount that is not defined as performance materiality.', 'easy', 1),

-- Q16: easy / L1 — Content of written deficiency communication
(1, 'Misstatements and Control Deficiencies', 'What must the auditor include in the written communication of significant deficiencies and material weaknesses to those charged with governance?', '["A statement that all internal controls are functioning effectively and no additional deficiencies exist", "A description of each deficiency and an explanation of its potential effects", "A detailed remediation plan with specific timelines for correcting each identified deficiency", "An assessment of the total financial impact of all control deficiencies on the current-year financial statements"]'::jsonb, 1, 'Under AU-C 265.12, the written communication must include a description of the significant deficiencies and material weaknesses and an explanation of their potential effects. The auditor is not required to provide remediation plans or quantify financial impact. Choice A is incorrect because the auditor explicitly states the communication is not intended to identify all deficiencies, and no assertion about overall control effectiveness is made.', 'easy', 1),

-- Q17: hard / L4 — Evaluating response when aggregate exceeds materiality
(1, 'Misstatements and Control Deficiencies', 'Near the completion of the audit of Westbrook Financial Advisors, the auditor determines that the aggregate of uncorrected misstatements totals $155,000, exceeding the overall materiality of $125,000. Management asserts the misstatements arise from reasonable estimation differences and refuses to make any adjustments. The auditor should evaluate whether to:', '["Accept management''s position and issue an unmodified opinion with an emphasis-of-matter paragraph noting the uncorrected misstatements", "Withdraw from the engagement because management''s refusal to correct material misstatements constitutes a scope limitation", "Issue a qualified or adverse opinion because the financial statements are materially misstated due to uncorrected misstatements", "Request management to sign a representation letter acknowledging the material misstatements, which allows an unmodified opinion"]'::jsonb, 2, 'Under AU-C 705.08, when the auditor concludes that uncorrected misstatements are material to the financial statements, the auditor must express a qualified or adverse opinion depending on pervasiveness. Management''s representation letter does not override the auditor''s independent judgment about materiality. Choice D is incorrect because a representation letter cannot substitute for correcting material misstatements or change the auditor''s opinion conclusion.', 'hard', 4),

-- Q18: hard / L4 — Recurring unremediated material weakness and engagement continuance
(1, 'Misstatements and Control Deficiencies', 'For the third consecutive year, the audit of Crestline Technologies reveals the same material weakness: lack of segregation of duties in the treasury function. Management acknowledges the deficiency each year but claims insufficient resources to hire additional staff. The audit committee has taken no corrective action. The engagement partner should recommend:', '["Issuing an adverse audit opinion on the financial statements due to the recurring unremediated material weakness", "Reducing the scope of treasury-related testing since the deficiency is already known and documented", "Accepting management''s resource constraint explanation and continuing to report the material weakness annually", "Discussing with the engagement quality reviewer whether the recurring deficiency affects the firm''s ability to continue the engagement"]'::jsonb, 3, 'Under AU-C 220.A24 and SQMS No. 1, the engagement partner must evaluate whether conditions such as recurring unremediated material weaknesses and inactive governance raise concerns about management integrity or the firm''s ability to perform the audit effectively. Choice A is incorrect because a material weakness in internal control does not automatically lead to an adverse opinion on the financial statements unless the statements themselves are materially misstated.', 'hard', 4),

-- Q19: medium / L2 — Timing of deficiency communication
(1, 'Misstatements and Control Deficiencies', 'During the October 2025 interim testing of Bayshore Logistics, the auditor identifies a material weakness in the cash disbursement authorization process. The audit report for the year ended December 31, 2025 is expected to be issued on March 15, 2026. Under AU-C 265, the auditor should communicate this material weakness:', '["Within 30 calendar days of the audit report release date", "In writing no later than 60 days after the audit report release date, though earlier communication is encouraged", "Orally during interim fieldwork and then confirm in writing only if the deficiency persists at year-end", "At the same time as the audit report is issued to ensure the communication reflects the final assessment"]'::jsonb, 1, 'Under AU-C 265.14, the auditor must communicate significant deficiencies and material weaknesses in writing no later than 60 days after the report release date. However, AU-C 265.A18 encourages timely communication so management and governance can take corrective action promptly. Choice C is incorrect because written communication is required regardless of whether the deficiency persists, and oral communication alone does not satisfy the standard.', 'medium', 2),

-- Q20: medium / L2 — Corrected misstatements still indicating control deficiency
(1, 'Misstatements and Control Deficiencies', 'During the audit of Thornbury Manufacturing for the year ended December 31, 2025, the auditor identifies $87,000 in revenue cutoff errors that management promptly corrects. The errors resulted from warehouse staff failing to match shipping documents with sales invoices before period-end close. Despite the corrections, the auditor should:', '["Remove the misstatements from consideration since management corrected them before the audit report date", "Document the misstatements only in the management representation letter", "Evaluate whether the $87,000 exceeds clearly trivial and add it to the summary of uncorrected misstatements", "Evaluate whether the underlying cause of the errors represents a control deficiency in the revenue cutoff process"]'::jsonb, 3, 'Under AU-C 265.A6, the auditor must consider the underlying cause of identified misstatements, not merely whether they were corrected. Even corrected misstatements may indicate control deficiencies if the errors resulted from inadequate controls. The failure to match shipping documents with invoices suggests a design or operating deficiency in revenue cutoff. Choice A is incorrect because correction does not eliminate the auditor''s obligation to assess control implications.', 'medium', 2),

-- Q21: medium / L3 — Management representation does not override auditor judgment
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cedar Point Industries, the auditor identifies $48,000 in uncorrected misstatements against an overall materiality of $60,000. Management provides a written representation that the uncorrected misstatements are immaterial. The auditor should consider the effect of this representation because:', '["Management''s representation conclusively resolves the auditor''s evaluation of the aggregate misstatements", "The representation shifts responsibility for the misstatements from the auditor to management", "The representation does not override the auditor''s independent assessment of whether the aggregate misstatements are material", "The auditor must accept management''s representation unless there is evidence of fraud"]'::jsonb, 2, 'Under AU-C 450.14, although the auditor obtains management''s written representation regarding the immateriality of uncorrected misstatements, this representation does not substitute for the auditor''s own evaluation. The auditor must independently assess whether the aggregate of $48,000 against $60,000 materiality—considering both quantitative proximity and qualitative factors—warrants opinion modification. Choice A is incorrect because management''s representation is only one input to the auditor''s judgment.', 'medium', 3),

-- Q22: easy / L1 — COSO control activities component
(1, 'Misstatements and Control Deficiencies', 'Under the COSO framework, which component of internal control addresses the policies and procedures that help ensure management directives are carried out?', '["Control activities", "Risk assessment", "Information and communication", "Monitoring activities"]'::jsonb, 0, 'Under AU-C 315 and the COSO Internal Control—Integrated Framework, control activities are the policies and procedures that help ensure management''s directives are carried out, including approvals, authorizations, verifications, reconciliations, and segregation of duties. Choice D (monitoring activities) is incorrect because monitoring evaluates whether controls are functioning over time rather than implementing management''s directives directly.', 'easy', 1),

-- Q23: medium / L3 — Qualitatively material misclassification affecting earnings target
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ridgeline Pharmaceuticals, the auditor identifies a $15,000 misclassification between research expense and development costs. Overall materiality is $500,000. However, the misclassification causes Ridgeline to meet an analyst consensus earnings target it would otherwise have missed. The auditor should analyze this misstatement because:', '["Any misstatement affecting whether an entity meets earnings targets automatically requires opinion modification", "The misstatement may be qualitatively material because it enables the entity to meet a specific financial benchmark it would otherwise miss", "Misclassifications between expense categories are always immaterial since total expenses remain unchanged", "The misstatement must be projected to the entire research and development population before materiality can be assessed"]'::jsonb, 1, 'Under AU-C 450.A20, the auditor must consider qualitative factors including whether a misstatement enables management to meet analyst expectations or masks a change in earnings trend. Even a quantitatively small misstatement may be material when it affects a key benchmark. Choice C is incorrect because misclassifications can be material when they affect financial statement line items that users rely upon for decision-making.', 'medium', 3),

-- Q24: easy / L1 — Management representation letter requirement
(1, 'Misstatements and Control Deficiencies', 'What must the auditor request from management regarding uncorrected misstatements identified during the audit?', '["A written representation that the effects of uncorrected misstatements are immaterial, individually and in the aggregate", "A signed acknowledgment that management is solely responsible for detecting all future misstatements", "A formal commitment to correct all uncorrected misstatements within the next fiscal quarter", "An oral confirmation during the closing conference that management considered the misstatements"]'::jsonb, 0, 'Under AU-C 450.14, the auditor must request a written representation from management that the effects of uncorrected misstatements are immaterial to the financial statements taken as a whole. This representation must be included in the management representation letter. Choice D is incorrect because an oral confirmation does not satisfy the requirement; the representation must be in writing as required by the standard.', 'easy', 1),

-- Q25: hard / L4 — Revising audit procedures after identifying material weakness
(1, 'Misstatements and Control Deficiencies', 'Midway through the audit of Apex Construction Group for the year ended December 31, 2025, the auditor identifies a material weakness in the change order approval process. The company has $28 million in active construction contracts. The engagement team has already completed substantive testing of contract revenue using a sample designed at the originally assessed control risk. The engagement partner should evaluate whether:', '["The completed substantive testing is sufficient because it was designed to detect material misstatements regardless of control risk", "The material weakness should be communicated immediately and the audit can proceed with the existing test results", "The nature, timing, and extent of substantive procedures should be revised to respond to the increased risk of material misstatement", "The engagement should be suspended until management remediates the change order approval deficiency"]'::jsonb, 2, 'Under AU-C 315.32 and AU-C 330.A42, when the auditor identifies a control deficiency that changes the assessed risk of material misstatement, the auditor must reconsider whether planned substantive procedures remain sufficient. A material weakness in change order approvals directly affects revenue recognition risk for construction contracts. Choice A is incorrect because substantive procedures designed at lower control risk may not provide sufficient evidence when control risk is reassessed higher.', 'hard', 4),

-- Q26: medium / L2 — Applying clearly trivial threshold to specific amounts
(1, 'Misstatements and Control Deficiencies', 'During the audit of Sterling Retail Group, the auditor sets overall materiality at $200,000 and the clearly trivial threshold at $4,000. The auditor identifies a $3,500 depreciation error and a $2,800 classification error. Under AU-C 450, the auditor should:', '["Accumulate both misstatements because they individually exceed 1% of materiality", "Accumulate only the $3,500 depreciation error because it is closer to the clearly trivial threshold", "Disregard both misstatements because they are each below performance materiality", "Disregard both misstatements because they are each below the $4,000 clearly trivial threshold"]'::jsonb, 3, 'Under AU-C 450.05, the auditor need not accumulate misstatements that are clearly trivial. Because both the $3,500 and $2,800 amounts fall below the auditor''s established clearly trivial threshold of $4,000, neither needs to be included in the summary of identified misstatements. Choice A is incorrect because the accumulation threshold is based on the clearly trivial amount established by the auditor, not a percentage-of-materiality rule.', 'medium', 2),

-- Q27: medium / L2 — Communicating deficiency below significant deficiency level
(1, 'Misstatements and Control Deficiencies', 'During the audit of Blue Harbor Shipping for the year ended December 31, 2025, the auditor identifies a control deficiency in the petty cash reconciliation process that does not rise to the level of a significant deficiency or material weakness. Under AU-C 265, the auditor:', '["Must communicate this deficiency in writing to those charged with governance along with significant deficiencies", "May communicate this deficiency to management but is not required to communicate it in writing to those charged with governance", "Must disregard the deficiency because AU-C 265 only applies to significant deficiencies and material weaknesses", "Should include this deficiency in the auditor''s report as an other-matter paragraph"]'::jsonb, 1, 'Under AU-C 265.A19, control deficiencies that are not significant deficiencies or material weaknesses may be communicated to management orally or in writing at the auditor''s discretion. AU-C 265.11 requires written communication only for significant deficiencies and material weaknesses. Choice C is incorrect because while AU-C 265 focuses on more severe deficiencies, it does not prohibit communication of lesser deficiencies to management.', 'medium', 2),

-- Q28: easy / L1 — Documentation requirements for accumulated misstatements
(1, 'Misstatements and Control Deficiencies', 'What documentation does the auditor maintain for misstatements accumulated during the audit?', '["A summary listing all identified misstatements and the conclusion on whether they are material in the aggregate", "Only misstatements that management refused to correct, excluding corrected items", "A narrative memorandum describing the general nature of misstatements without specific dollar amounts", "Documentation only for misstatements that exceed performance materiality individually"]'::jsonb, 0, 'Under AU-C 450.15, the auditor must document all identified misstatements accumulated during the audit, whether corrected or uncorrected, and the conclusion about whether uncorrected misstatements are material individually and in the aggregate. Choice B is incorrect because the auditor must document all accumulated misstatements, including those that management subsequently corrected, to support the overall evaluation of audit results.', 'easy', 1),

-- Q29: easy / L1 — Distinguishing material weakness from significant deficiency
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what distinguishes a material weakness from a significant deficiency in internal control?', '["A material weakness involves fraud while a significant deficiency involves only errors", "A material weakness must be identified by external auditors while a significant deficiency can be self-reported", "A material weakness involves a reasonable possibility that a material misstatement will not be prevented or detected on a timely basis", "A material weakness affects the balance sheet while a significant deficiency affects only the income statement"]'::jsonb, 2, 'Under AU-C 265.07, a material weakness is a deficiency, or combination of deficiencies, in internal control such that there is a reasonable possibility that a material misstatement will not be prevented or detected and corrected on a timely basis. A significant deficiency is less severe but still merits governance attention. Choice A is incorrect because both material weaknesses and significant deficiencies can arise from either errors or fraud-related control failures.', 'easy', 1),

-- Q30: medium / L2 — Reassessing materiality when misstatements accumulate
(1, 'Misstatements and Control Deficiencies', 'During the audit of Golden Prairie Agriculture for the year ended September 30, 2025, accumulated identified misstatements reach $72,000, which is 85% of the $85,000 overall materiality. The auditor had originally set performance materiality at $63,750. Under AU-C 320, the auditor should:', '["Immediately qualify the audit opinion because the accumulated misstatements approach materiality", "Accept the misstatements without further action because they do not exceed overall materiality", "Evaluate whether the overall materiality level remains appropriate and consider whether additional procedures are needed to detect further misstatements", "Reduce performance materiality to zero for all remaining substantive testing"]'::jsonb, 2, 'Under AU-C 320.13, the auditor must revise materiality if information comes to attention during the audit that would have caused a different amount to be established initially. When accumulated misstatements approach materiality, the auditor should evaluate whether remaining undetected misstatements could cause the aggregate to exceed materiality. Choice B is incorrect because proximity to materiality requires the auditor to perform additional evaluation, not simply accept the results.', 'medium', 2)
;

COMMIT;
